package tw.radar.shortscan;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;import okhttp3.*;import java.util.*;import java.util.concurrent.TimeUnit;
public class ExtremeActivity extends Activity {
 static final String[] KEYS={"foreign5","foreign10","foreign15","big_down","small_up","short_up","margin_down","foreign_down","small70","short_ratio","price100","red_down","daily_down","near_low","volume500"};
 static final String[] LABELS={"外資及陸資持股 < 5%","外資及陸資持股 < 10%","外資及陸資持股 < 15%","大戶減持（>400張級距）","散戶增持（10張以下）","融券餘額增加","融資餘額減少","外資及陸資占比下降","散戶持股 >70%","券資比 >30%","收盤價 >100元","收盤低於開盤（黑K）","日跌幅 >3%","收盤位於日內振幅底部20%","日成交量 >500張"};
 private final CheckBox[] checks=new CheckBox[KEYS.length];private boolean changing=false;private SharedPreferences p;private TextView status;private LinearLayout results;private Button scan,demo;private final OkHttpClient client=new OkHttpClient.Builder().callTimeout(180,TimeUnit.SECONDS).build();private Call current;private PublicScanner publicScanner;private Thread worker;
 @Override public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences(RadarService.PREF,MODE_PRIVATE);ScrollView sv=new ScrollView(this);sv.setBackgroundColor(Ui.BG);LinearLayout root=Ui.col(this);int pad=Ui.dp(this,16);root.setPadding(pad,pad,pad,pad);sv.addView(root);setContentView(sv);Button back=Ui.button(this,"返回盤中雷達");back.setOnClickListener(v->finish());Ui.add(root,back);Ui.add(root,Ui.text(this,"全市場極空掃描",25,Ui.MINT,true));Ui.add(root,Ui.text(this,"上市櫃普通股｜官方盤後籌碼｜v0.3.1",12,Ui.MUTED,false));Ui.add(root,Ui.text(this,"勾選項目全部必須成立（AND）。外資三檔門檻互斥；缺資料不列入候選。",13,Ui.FG,false));Set<String> saved=p.getStringSet("extreme_selected",new HashSet<>(Arrays.asList("foreign10","big_down","small_up","short_up","margin_down")));LinearLayout group=Ui.card(this);Ui.add(group,Ui.text(this,"必要條件 · 使用者指定",16,Ui.GOLD,true));for(int i=0;i<KEYS.length;i++){if(i==7){Ui.add(root,group);group=Ui.card(this);Ui.add(group,Ui.text(this,"AI 研究新增候選條件（待回測）",16,Ui.GOLD,true));}CheckBox c=new CheckBox(this);checks[i]=c;c.setText(LABELS[i]);c.setTextColor(Ui.FG);c.setTextSize(14);c.setChecked(saved.contains(KEYS[i]));int k=i;c.setOnCheckedChangeListener((v,on)->{if(changing)return;if(on&&k<3){changing=true;for(int j=0;j<3;j++)if(j!=k&&checks[j]!=null)checks[j].setChecked(false);changing=false;}save();});group.addView(c);}Ui.add(root,group);LinearLayout controls=Ui.card(this);scan=Ui.button(this,"開始全市場掃描（免後端）");scan.setOnClickListener(v->start(false));controls.addView(scan);demo=Ui.button(this,"試跑模擬資料（非真實行情）");demo.setOnClickListener(v->start(true));controls.addView(demo);status=Ui.text(this,"尚未掃描",13,Ui.MUTED,false);controls.addView(status);Ui.add(root,controls);results=Ui.col(this);Ui.add(root,results);Ui.add(root,Ui.text(this,"低外資持股與融券增加不代表一定下跌，融券偏高亦可能軋空。股權級距不能直接識別特定大戶或散戶。此功能是候選篩選，非交易指令。",12,Ui.MUTED,false));}
 private void save(){HashSet<String> set=new HashSet<>();for(int i=0;i<KEYS.length;i++)if(checks[i]!=null&&checks[i].isChecked())set.add(KEYS[i]);p.edit().putStringSet("extreme_selected",set).apply();}
 private JSONArray selected(){JSONArray a=new JSONArray();for(int i=0;i<KEYS.length;i++)if(checks[i].isChecked())a.put(KEYS[i]);return a;}
 private void busy(boolean b){scan.setEnabled(!b);demo.setEnabled(!b);for(CheckBox c:checks)c.setEnabled(!b);}
 private void start(boolean mock){JSONArray sel=selected();results.removeAllViews();if(sel.length()==0){status.setText("請至少勾選一項必要條件");return;}if(mock){show(mock(sel),true);return;}busy(true);status.setText("直接連線官方資料，不需要設定後端…");publicScanner=new PublicScanner(getApplicationContext(),message->runOnUiThread(()->{if(!isDestroyed())status.setText(message);}));worker=new Thread(()->{try{JSONObject j=publicScanner.run(sel);runOnUiThread(()->{if(!isDestroyed()){busy(false);show(j,false);}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){busy(false);status.setText("掃描異常："+e.getMessage()+"。未產生正式名單。");}});}},"public-market-scan");worker.start();}
 private String label(String k){for(int i=0;i<KEYS.length;i++)if(KEYS[i].equals(k))return LABELS[i];return k;}
 private String labels(JSONArray a){StringBuilder b=new StringBuilder();if(a!=null)for(int i=0;i<a.length();i++)b.append(i==0?"":"、").append(label(a.optString(i)));return b.toString();}
 private void show(JSONObject j,boolean mock){results.removeAllViews();JSONArray a=j.optJSONArray("results");JSONObject m=j.optJSONObject("markets"),err=j.optJSONObject("errors");String summary=(mock?"【模擬測試，不是真實股票】":"資料檢查日："+j.optString("as_of","未知"))+"\n已掃描 "+j.optInt("scanned")+" 檔｜符合 "+j.optInt("matched")+" 檔\n不符 "+j.optInt("failed")+"｜必要資料缺失 "+j.optInt("unknown");if(m!=null)summary+="\n上市 "+m.optInt("TWSE")+"｜上櫃 "+m.optInt("TPEX");if(!mock&&!j.optBoolean("complete"))summary+="\n⚠ 部分來源或市場未完整，不能視為全市場完整結論。";if(err!=null&&err.length()>0)summary+="\n資料異常："+err.toString();JSONObject missing=j.optJSONObject("missing");if(missing!=null&&missing.length()>0){Iterator<String> it=missing.keys();while(it.hasNext()){String k=it.next();summary+="\n缺少 "+label(k)+"："+missing.optInt(k)+" 檔";}}status.setText(summary);if(a==null||a.length()==0){Ui.add(results,Ui.text(this,"沒有符合的可驗證候選（不代表市場不存在空方股）",14,Ui.MUTED,false));return;}for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;LinearLayout c=Ui.card(this);Ui.add(c,Ui.text(this,x.optString("symbol")+" "+x.optString("name")+" · "+x.optString("market"),18,Ui.MINT,true));Ui.add(c,Ui.text(this,"必要："+labels(x.optJSONArray("matched")),13,Ui.FG,true));Ui.add(c,Ui.text(this,"額外命中："+labels(x.optJSONArray("extra_hits")),12,Ui.MUTED,false));Ui.add(c,Ui.text(this,"外資及陸資 "+Ui.num(x,"foreign")+"%｜大戶變動 "+Ui.num(x,"big_delta")+" 個百分點\n散戶變動 "+Ui.num(x,"small_delta")+" 個百分點｜散戶占比 "+Ui.num(x,"small")+"%\n融券變動 "+Ui.num(x,"short_delta")+"｜融資變動 "+Ui.num(x,"margin_delta")+"\n收盤 "+Ui.num(x,"close")+"｜日漲跌 "+Ui.num(x,"change_pct")+"%",13,Ui.FG,false));Ui.add(c,Ui.text(this,"資料日期："+x.optString("dates","未取得"),11,Ui.MUTED,false));Button detail=Ui.button(this,"全部條件與來源");detail.setOnClickListener(v->{JSONObject st=x.optJSONObject("states");StringBuilder b=new StringBuilder();for(int k=0;k<KEYS.length;k++)b.append(st==null||st.isNull(KEYS[k])?"？":st.optBoolean(KEYS[k])?"✓":"×").append(" ").append(LABELS[k]).append("\n");b.append("\n資料來源：").append(j.optString("sources","模擬"));new AlertDialog.Builder(this).setTitle(x.optString("name")+" 條件明細").setMessage(b.toString()).setPositiveButton("關閉",null).show();});c.addView(detail);Ui.add(results,c);}}
 private JSONObject mock(JSONArray sel){try{JSONArray arr=new JSONArray();int fail=0,unknown=0;for(int n=0;n<3;n++){JSONObject st=new JSONObject();for(int i=0;i<KEYS.length;i++)st.put(KEYS[i],n!=1||i!=5);st.put("foreign5",n==0);st.put("foreign10",n<2);st.put("foreign15",true);if(n==2)st.put("big_down",JSONObject.NULL);boolean ok=true,missing=false;for(int i=0;i<sel.length();i++){String k=sel.getString(i);missing|=st.isNull(k);ok&=st.optBoolean(k);}if(missing){unknown++;continue;}if(!ok){fail++;continue;}JSONArray extra=new JSONArray();for(int i=3;i<KEYS.length;i++){boolean chosen=false;for(int q=0;q<sel.length();q++)chosen|=KEYS[i].equals(sel.optString(q));if(!chosen&&st.optBoolean(KEYS[i]))extra.put(KEYS[i]);}arr.put(new JSONObject().put("symbol","DEMO-"+(n+1)).put("name","測試標的").put("market","模擬").put("matched",sel).put("extra_hits",extra).put("states",st));}return new JSONObject().put("scanned",3).put("matched",arr.length()).put("failed",fail).put("unknown",unknown).put("results",arr);}catch(Exception e){return new JSONObject();}}
 @Override protected void onDestroy(){if(current!=null)current.cancel();if(worker!=null)worker.interrupt();if(publicScanner!=null)publicScanner.cancel();super.onDestroy();}
}